const Text = props => {
    const [value, setValue] = createSignal('')
    const [loading, setLoading] = createSignal(false)
    let timer: NodeJS.Timeout

    return (
        <Input
            {...props}
            value={value()}
            loading={props.loading || loading()}
            onInput={event => {
                clearTimeout(timer)
                setLoading(true)
                setValue(event.target.value)

                timer = setTimeout(() => {
                    setLoading(false)
                }, 800)
            }}
        />
    )
};

